/// Looks up a primary composite for a (starter, combiner) pair
/// Returns null if no composite exists
pub fn getComposite(starter: Codepoint, combiner: Codepoint) ?Codepoint {
    // Check Hangul first (algorithmic composition)
    if (composeHangul(starter, combiner)) |composite| {
        return composite;
    }

    // Binary search in composition table
    var left: usize = 0;
    var right: usize = composition_pairs.len;
    while (left < right) {
        const mid = left + (right - left) / 2;
        const entry = composition_pairs[mid];
        if (entry.starter == starter and entry.combiner == combiner) {
            return entry.composite;
        } else if (entry.starter < starter or (entry.starter == starter and entry.combiner < combiner)) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return null;
}

/// Hangul syllable composition constants
const HANGUL = struct {
    const S_BASE: u21 = 0xAC00;
    const L_BASE: u21 = 0x1100;
    const V_BASE: u21 = 0x1161;
    const T_BASE: u21 = 0x11A7;
    const L_COUNT: u21 = 19;
    const V_COUNT: u21 = 21;
    const T_COUNT: u21 = 28;
    const N_COUNT: u21 = V_COUNT * T_COUNT;
    const S_COUNT: u21 = L_COUNT * N_COUNT;
};

/// Composes Hangul jamo algorithmically
fn composeHangul(first: Codepoint, second: Codepoint) ?Codepoint {
    // Check for L + V -> LV
    if (first >= HANGUL.L_BASE and first < HANGUL.L_BASE + HANGUL.L_COUNT) {
        if (second >= HANGUL.V_BASE and second < HANGUL.V_BASE + HANGUL.V_COUNT) {
            const l_index = first - HANGUL.L_BASE;
            const v_index = second - HANGUL.V_BASE;
            return HANGUL.S_BASE + (l_index * HANGUL.N_COUNT) + (v_index * HANGUL.T_COUNT);
        }
    }

    // Check for LV + T -> LVT
    if (first >= HANGUL.S_BASE and first < HANGUL.S_BASE + HANGUL.S_COUNT) {
        const s_index = first - HANGUL.S_BASE;
        if (s_index % HANGUL.T_COUNT == 0) {
            if (second > HANGUL.T_BASE and second < HANGUL.T_BASE + HANGUL.T_COUNT) {
                return first + (second - HANGUL.T_BASE);
            }
        }
    }

    return null;
}
